<?php require_once __DIR__ . '/../bootstrap.php'; $csrf=csrf_token(); ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#171715"><title>ANOR COFFEE — Админ-панель</title><link rel="stylesheet" href="/assets/admin.css"><script defer src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script></head><body>
<main class="wrap"><header><div><small>ANOR COFFEE</small><h1>Панель управления</h1></div><button id="logout" class="ghost hidden">Выйти</button></header>
<section id="login" class="box"><h2>Вход для сотрудников</h2><form id="loginForm"><label>Логин<input name="username" autocomplete="username" required></label><label>Пароль<input name="password" type="password" autocomplete="current-password" required></label><button class="gold">Войти</button><p id="loginError" class="error"></p></form></section>
<section id="dashboard" class="hidden">
<div class="stats"><div class="box"><small>Клиентов</small><b id="totalMembers">0</b></div><div class="box"><small>Доступно подарков</small><b id="totalRewards">0</b></div></div>
<div class="box scanner"><h2>Сканирование карты</h2><p>Наведите камеру на QR-код клиента. Разрешите доступ к камере в браузере.</p><div id="reader"></div><button id="startScan" class="gold">Включить камеру</button><button id="stopScan" class="ghost hidden">Остановить камеру</button><div class="or">или введите QR-токен вручную</div><form id="manualForm"><input name="qr" placeholder="Вставьте ссылку или токен карты"><button class="ghost">Найти карту</button></form><p id="scanError" class="error"></p></div>
<div id="clientCard" class="box hidden"><div class="client-head"><div><small>КАРТА КЛИЕНТА</small><h2 id="clientName">—</h2><p id="clientMeta"></p></div><div class="counter" id="clientStamps">0/10</div></div><div class="mini-track"><i id="clientBar"></i></div><p id="clientReward" class="reward"></p><div class="client-actions"><button id="addStamp" class="gold">＋ Начислить 1 штамп</button><button id="redeem" class="ghost hidden">Выдать подарок и начать новый цикл</button></div></div>
<div class="box"><div class="section-head"><h2>Последние клиенты</h2><button id="refresh" class="ghost">Обновить</button></div><div class="table-wrap"><table><thead><tr><th>Клиент</th><th>Телефон</th><th>Штампы</th><th>Дата регистрации</th></tr></thead><tbody id="membersTable"></tbody></table></div></div>
<div class="box"><h2>История операций</h2><div class="table-wrap"><table><thead><tr><th>Операция</th><th>Клиент</th><th>Сотрудник</th><th>Дата</th></tr></thead><tbody id="txTable"></tbody></table></div></div>
</section></main><div id="toast" class="toast"></div>
<script>
let csrf=<?=json_encode($csrf)?>, scanner=null, selected=null, scanning=false;
const $=id=>document.getElementById(id);
const api=async(path,body=null)=>{const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка запроса');if(d.csrf)csrf=d.csrf;return d};
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2500)}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setLogged(v){$('login').classList.toggle('hidden',v);$('dashboard').classList.toggle('hidden',!v);$('logout').classList.toggle('hidden',!v);if(v)loadStats()}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('admin-login.php',{username:f.get('username'),password:f.get('password')});csrf=d.csrf;setLogged(true)}catch(err){$('loginError').textContent=err.message}});
$('logout').onclick=async()=>{try{await api('admin-logout.php',{})}catch(e){}setLogged(false)};
async function loadStats(){try{const d=await api('admin-stats.php');$('totalMembers').textContent=d.stats.members;$('totalRewards').textContent=d.stats.rewards;$('membersTable').innerHTML=d.members.map(m=>`<tr><td>${escapeHtml(m.name)}<small>${escapeHtml(m.public_id)}</small></td><td>${escapeHtml(m.phone)}</td><td>${m.stamps}/10 ${m.reward_ready?'🎁':''}</td><td>${escapeHtml(m.created_at)}</td></tr>`).join('');$('txTable').innerHTML=d.transactions.map(t=>`<tr><td>${escapeHtml(t.action==='stamp'?'Штамп':t.action==='reward_redeemed'?'Подарок':'Корректировка')}</td><td>${escapeHtml(t.name)}</td><td>${escapeHtml(t.username||'—')}</td><td>${escapeHtml(t.created_at)}</td></tr>`).join('')}catch(e){toast(e.message)}}
$('refresh').onclick=loadStats;
async function lookup(qr){$('scanError').textContent='';try{const d=await api('admin-scan.php',{qr});selected=d.member;renderClient()}catch(e){$('scanError').textContent=e.message;$('clientCard').classList.add('hidden')}}
function renderClient(){const m=selected;$('clientCard').classList.remove('hidden');$('clientName').textContent=m.name;$('clientMeta').textContent=m.phone+' · '+m.publicId;$('clientStamps').textContent=m.stamps+'/10';$('clientBar').style.width=(m.stamps*10)+'%';$('clientReward').textContent=m.rewardReady?'Подарок доступен. После выдачи нажмите «Выдать подарок».':'До подарка осталось '+(10-m.stamps)+' штампов.';$('addStamp').classList.toggle('hidden',m.rewardReady||m.stamps>=10);$('redeem').classList.toggle('hidden',!m.rewardReady)}
$('manualForm').onsubmit=e=>{e.preventDefault();lookup(new FormData(e.currentTarget).get('qr'))};
$('addStamp').onclick=async()=>{if(!selected)return;try{const d=await api('admin-stamp.php',{memberId:selected.id,requestId:crypto.randomUUID()});selected.stamps=d.stamps;selected.rewardReady=d.rewardReady;renderClient();loadStats();toast(d.rewardReady?'10 штампов! Подарок доступен.':'Штамп начислен')}catch(e){toast(e.message)}};
$('redeem').onclick=async()=>{if(!selected||!confirm('Подтвердить выдачу бесплатного напитка и обнулить 10 штампов?'))return;try{await api('admin-redeem.php',{memberId:selected.id});selected.stamps=0;selected.rewardReady=false;renderClient();loadStats();toast('Подарок отмечен как выданный')}catch(e){toast(e.message)}};
$('startScan').onclick=async()=>{try{if(!window.Html5Qrcode)throw Error('Библиотека сканера не загрузилась. Проверьте интернет.');scanner=new Html5Qrcode('reader');await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},async text=>{await scanner.stop();scanning=false;$('startScan').classList.remove('hidden');$('stopScan').classList.add('hidden');lookup(text)},()=>{});scanning=true;$('startScan').classList.add('hidden');$('stopScan').classList.remove('hidden')}catch(e){$('scanError').textContent='Не удалось включить камеру: '+e.message+' Проверьте HTTPS и разрешение камеры.'}};
$('stopScan').onclick=async()=>{if(scanner&&scanning){await scanner.stop();scanning=false}$('startScan').classList.remove('hidden');$('stopScan').classList.add('hidden')};
(async()=>{try{const d=await api('admin-session.php');setLogged(d.authenticated)}catch(e){setLogged(false)}})();
</script></body></html>
